{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "country",
      "as": "agg1",
      "group_by": ["GovernmentForm"],
      "metrics": [
        {
          "as": "avg_life",
          "fn": "mean",
          "column": "LifeExpectancy"
        },
        {
          "as": "total_population",
          "fn": "sum",
          "column": "Population"
        }
      ]
    },
    {
      "op": "filter",
      "input": "agg1",
      "as": "filtered",
      "where": "avg_life > 72"
    },
    {
      "op": "rename",
      "input": "filtered",
      "as": "renamed",
      "columns": {
        "GovernmentForm": "government form name",
        "total_population": "total population"
      }
    },
    {
      "op": "select",
      "input": "renamed",
      "as": "output",
      "columns": ["government form name", "total population"]
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "country",
      "as": "agg",
      "group_by": ["Continent"],
      "metrics": [
        {
          "as": "AvgLifeExpectancy",
          "fn": "mean",
          "column": "LifeExpectancy"
        },
        {
          "as": "TotalPopulation",
          "fn": "sum",
          "column": "Population"
        }
      ]
    },
    {
      "op": "filter",
      "input": "agg",
      "as": "filtered",
      "where": "AvgLifeExpectancy < 72"
    },
    {
      "op": "rename",
      "input": "filtered",
      "as": "renamed",
      "columns": {
        "AvgLifeExpectancy": "average life expectancy",
        "TotalPopulation": "total population"
      }
    },
    {
      "op": "select",
      "input": "renamed",
      "as": "result",
      "columns": ["Continent", "average life expectancy", "total population"]
    }
  ]
}

